const D=window.CREATOR_COMMERCE_DEMO,R=D.contentResults,C=D.creators;
const $=id=>document.getElementById(id),money=n=>'R$ '+Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
let rows=[...R.contents],sortDesc=true,openContentId=null;
const creator=id=>C.find(x=>x.id===id);
function totals(){return rows.reduce((a,x)=>({orders:a.orders+x.orders,revenue:a.revenue+x.revenue,settledOrders:a.settledOrders+x.settledOrders,settledRevenue:a.settledRevenue+x.settledRevenue,provisionalOrders:a.provisionalOrders+x.provisionalOrders,provisionalRevenue:a.provisionalRevenue+x.provisionalRevenue}),{orders:0,revenue:0,settledOrders:0,settledRevenue:0,provisionalOrders:0,provisionalRevenue:0})}
function renderSummary(){const t=totals();$('attrRevenue').textContent=money(t.revenue);$('attrOrders').textContent=t.orders+' pedidos atribuídos';$('settledOrders').textContent=t.settledOrders;$('settledRevenue').textContent=money(t.settledRevenue);$('provOrders').textContent=t.provisionalOrders;$('provRevenue').textContent=money(t.provisionalRevenue);$('contentCount').textContent=rows.length;const pct=t.orders?t.settledOrders/t.orders*100:0;$('settledPct').textContent=pct.toFixed(1).replace('.',',')+'%';$('provPct').textContent=(100-pct).toFixed(1).replace('.',',')+'%';$('settledBar').style.width=pct+'%'}
function filteredRows(){const q=$('globalSearch').value.toLowerCase().trim(),type=$('typeFilter').value,cid=$('creatorFilter').value;return rows.filter(x=>{const c=creator(x.creatorId);return (!q||(x.title+' '+c.n+' '+x.type).toLowerCase().includes(q))&&(type==='all'||x.type===type)&&(cid==='all'||String(x.creatorId)===cid)})}
function renderRows(){$('contentRows').innerHTML=filteredRows().map(x=>{const c=creator(x.creatorId),eff=x.views?(x.orders/x.views*1000).toFixed(2).replace('.',','):'—';return "<tr><td><div class='contentCell'><div class='thumb'>"+x.type+"</div><div><b>"+x.title+"</b><div class='sub'>"+x.source+" · freshness "+x.freshness+"</div></div></div></td><td>"+c.n+"</td><td>"+x.publishedAt+"</td><td>"+x.views.toLocaleString('pt-BR')+"</td><td>"+x.orders+"</td><td>"+eff+"</td><td>"+x.settledOrders+"</td><td>"+x.provisionalOrders+"</td><td>"+money(x.revenue)+"</td><td><button class='btn detail' data-id='"+x.id+"'>Abrir</button></td></tr>"}).join('');document.querySelectorAll('.detail').forEach(b=>b.onclick=()=>openDetail(b.dataset.id))}
function renderContext(){$('businessOrders').textContent=R.businessContext.orders;$('businessRevenue').textContent=money(R.businessContext.revenue);$('businessPeriod').textContent=R.businessContext.period;$('businessSource').textContent=R.businessContext.source;$('businessFreshness').textContent=R.businessContext.freshness}
function renderLearning(){$('learningRows').innerHTML=R.learning.map(x=>{const c=creator(x.creatorId);return "<div class='learningRow'><div class='creator'>"+c.n+"<div class='sub'>"+c.h+"</div></div><div><span class='sub'>Recomendação</span><br><b>"+x.recommendation+"</b></div><div><span class='sub'>Decisão</span><br><b>"+x.decision+"</b></div><div><span class='sub'>Ação</span><br>"+x.action+"</div><div><span class='sub'>Resultado</span><br>"+x.result+"</div></div>"}).join('')}
function openDetail(id){const x=rows.find(v=>v.id===id),c=creator(x.creatorId);openContentId=id;$('detailTitle').textContent=x.title;$('detailMeta').textContent=c.n+' · '+x.publishedAt+' · '+x.source;$('detailPreview').textContent=x.type;$('detailViews').textContent=x.views.toLocaleString('pt-BR');$('detailOrders').textContent=x.orders;$('detailSettled').textContent=x.settledOrders;$('detailProv').textContent=x.provisionalOrders;$('detailRevenue').textContent=money(x.revenue);$('detailSource').textContent=x.source;$('detailFreshness').textContent=x.freshness;const b=$('openPublishedContent');b.disabled=!x.link;b.title=x.link?'Abrir conteúdo original':x.linkReason;b.textContent=x.link?'Abrir conteúdo publicado':'Link indisponível neste DEMO';$('modalOverlay').classList.add('show');$('detailModal').classList.add('show')}
function close(){ $('modalOverlay').classList.remove('show');$('detailModal').classList.remove('show')}
$('closeDetail').onclick=close;$('modalOverlay').onclick=close;$('globalSearch').oninput=renderRows;$('typeFilter').onchange=renderRows;$('creatorFilter').onchange=renderRows;$('openPublishedContent').onclick=()=>{const x=rows.find(v=>v.id===openContentId);if(x?.link)location.href=x.link};$('sortBtn').onclick=()=>{sortDesc=!sortDesc;rows.sort((a,b)=>(a.revenue-b.revenue)*(sortDesc?-1:1));renderRows();toast('Ordenação por receita '+(sortDesc?'decrescente':'crescente'))};
$('periodBtn').onclick=()=>toast('Período fixado em 30 dias neste protótipo');$('userBtn').onclick=()=>toast('Workspace Principal · Daniel Santos');$('market').onchange=()=>toast('Somente Brasil · TikTok Shop disponível neste protótipo');
$('openEconomics').onclick=()=>location.href='../unit-economics/index.html';$('openCampaign').onclick=()=>location.href='../campaign/index.html';$('showLearning').onclick=()=>document.querySelector('.learningCard').scrollIntoView({behavior:'smooth'});
$('navSku').onclick=()=>location.href='../sku-opportunity/index.html';$('navShortlist').onclick=()=>location.href='../creator-shortlist/index.html';$('navOutreach').onclick=()=>location.href='../outreach/index.html';$('navCampaign').onclick=()=>location.href='../campaign/index.html';$('navEconomics').onclick=()=>location.href='../unit-economics/index.html';
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',1600)}
[...new Map(rows.map(x=>[x.creatorId,creator(x.creatorId)])).values()].forEach(c=>$('creatorFilter').insertAdjacentHTML('beforeend',"<option value='"+c.id+"'>"+c.n+"</option>"));
renderSummary();renderContext();renderRows();renderLearning();